def data(self, *keys):
    result = {}
    for key in keys:
        if isinstance(key, int):
            if key < 0 or key >= len(self):
                raise IndexError(f"Index out of bounds: {key}")
            result[key] = self[key]
        elif isinstance(key, str):
            if key not in self:
                result[key] = None
            else:
                result[key] = self[key]
        else:
            raise TypeError(f"Invalid key type: {type(key)}")
    if not keys:
        result = {k: self[k] for k in self}
    return result

