def extostr(cls, e, max_level=30, max_path_level=5):
        """
        Format an exception.
        :param e: Any exception instance.
        :type e: Exception
        :param max_level: Maximum call stack level (default 30)
        :type max_level: int
        :param max_path_level: Maximum path level (default 5)
        :type max_path_level: int
        :return The exception readable string
        :rtype str
        """
        import traceback

        def format_traceback(exc_type, exc_value, exc_traceback, level):
            if level > max_level:
                return "..."
            tb = traceback.extract_tb(exc_traceback)
            if len(tb) > max_path_level:
                tb = tb[:max_path_level]
            return "\n".join(traceback.format_list(tb))

        return format_traceback(
            type(e), e, e.__traceback__, 0
        ) + "\n\n" + str(e)

