def formatmany(self, sql: AnyStr, many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]]) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    if isinstance(sql, bytes):
        sql = sql.decode('utf-8')

    formatted_sql = sql
    converted_params = []

    if isinstance(many_params[0], Mapping):
        in_style = 'named'
    else:
        in_style = 'ordinal'

    for params in many_params:
        if in_style == 'named':
            out_params = {f'@{k}': v for k, v in params.items()}
        else:
            out_params = params[:]

        formatted_sql = formatted_sql.replace('?', '@?')
        converted_params.append(out_params)

    if isinstance(sql, bytes):
        formatted_sql = formatted_sql.encode('utf-8')

    return formatted_sql, converted_params

