def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def apply_absorption(expr):
        if isinstance(expr, tuple) and len(expr) == 2:
            op = expr[0]
            operands = expr[1]
            if isinstance(operands, tuple) and len(operands) == 2:
                op1, op2 = operands
                if op == '&':
                    if op1 == op2:
                        return op1
                    elif (op1 == '~' and op2[0] == '|' and op2[1][0] == '~' and op2[1][1] == op1[1]) or (op2 == '~' and op1[0] == '|' and op1[1][0] == '~' and op1[1][1] == op2[1]):
                        return (op, (op1[1], op2[1]))
                elif op == '|':
                    if op1 == op2:
                        return op1
                    elif (op1 == '~' and op2[0] == '&' and op2[1][0] == '~' and op2[1][1] == op1[1]) or (op2 == '~' and op1[0] == '&' and op1[1][0] == '~' and op1[1][1] == op2[1]):
                        return (op, (op1[1], op2[1]))
        return expr

    return [apply_absorption(expr) for expr in args]

