def validate_version_inventories(version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    root_inventory = {}
    content_digests = {}

    for version_dir in version_dirs:
        # Load inventory for the current version directory
        inventory = load_inventory(version_dir)
        if not inventory:
            raise ValueError(f"No inventory found for version {version_dir}")

        # Check if the inventory is complete
        if not inventory.is_complete():
            raise ValueError(f"Incomplete inventory for version {version_dir}")

        # Update the root inventory with the current version's inventory
        root_inventory.update(inventory)

        # Check content digests
        for digest in inventory.content_digests:
            if digest not in root_inventory.content_digests:
                content_digests[digest] = inventory.version

    return content_digests

