def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    import ROOT
    graph = ROOT.TGraphErrors()
    if make_value is None:
        make_value = lambda x: x
    for bin_ in hist:
        x = 0
        y = 0
        if get_coordinate == "left":
            x = bin_.x - bin_.width / 2
        elif get_coordinate == "right":
            x = bin_.x + bin_.width / 2
        elif get_coordinate == "middle":
            x = bin_.x
        if scale is True:
            y = bin_.content * hist.GetXaxis().GetBinWidth(bin_.x)
        else:
            y = bin_.content
        point = make_value(y)
        if isinstance(point, tuple):
            graph.SetPoint(graph.GetN(), x, point[0])
            if len(point) > 1:
                graph.SetPointEYhigh(graph.GetN() - 1, point[1])
        else:
            graph.SetPoint(graph.GetN(), x, point)
    graph.SetTitle(";".join(field_names))
    return graph

