def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags = set()
    in_code_block = False
    current_tag = ""
    replaced_text = []
    lines = text.split('\n')

    for line in lines:
        if line.strip().startswith('```'):
            in_code_block = not in_code_block
            replaced_text.append(line)
            continue

        if in_code_block:
            replaced_text.append(line)
            continue

        words = line.split()
        for word in words:
            if word.startswith('#'):
                current_tag = word[1:]
                if replacer:
                    current_tag = replacer(current_tag)
                tags.add(current_tag)
                replaced_text.append(current_tag)
            else:
                if current_tag:
                    replaced_text.append(current_tag)
                    current_tag = ""
                replaced_text.append(word)

    if current_tag:
        replaced_text.append(current_tag)

    return tags, ' '.join(replaced_text)

