def parse_diaspora_webfinger(document: str) -> Dict:
    if document.startswith("{"):
        import json
        return json.loads(document)
    elif document.startswith("<xrd"):
        import xml.etree.ElementTree as ET
        root = ET.fromstring(document)
        subject = root.find("{http://www.w3.org/2005/app}Subject").text
        links = {}
        for link in root.findall("{http://www.w3.org/2005/app}Link"):
            rel = link.get("rel")
            href = link.get("href")
            if rel and href:
                links[rel] = href
        return {"subject": subject, "links": links}
    else:
        raise ValueError("Unsupported webfinger document format")

